INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 1, 62, "ミッションをクリアすると、\n報酬がもらえますよ！\n頑張ってください", "2030/01/01 14:59:59", 3.414, 1, 2, 190801, "2025/01/31 12:00:00", -416.5, "カリン", 1000001, 1);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 2, 62, "ミッションをクリアして、\n報酬をゲットしましょう！", "2030/01/01 14:59:59", 3.099, 1, 2, 190801, "2025/01/31 12:00:00", -416.5, "カリン", 1000002, 1);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 3, 63, "受け取ることができる\n報酬があるようです\n確認してみてください", "2030/01/01 14:59:59", 2.801, 1, 2, 190801, "2025/01/31 12:00:00", -416.5, "カリン", 1000003, 1);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 4, 63, "報酬がもらえますよ！\nチェックしてみてください", "2030/01/01 14:59:59", 0, 2, 2, 190801, "2025/01/31 12:00:00", -416.5, "カリン", 1000004, 1);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 5, 64, "ギルド管理協会です！\nイベント報酬券をお持ちでしたら、様々なアイテムと交換できますよ", "2030/01/01 14:59:59", 2.12, 2, 1, 190801, "2025/01/31 12:00:00", -363, "カリン", 1000005, 1);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 6, 64, "お疲れさまです！\nこちらでイベント報酬券とアイテムを交換することができますよ", "2030/01/01 14:59:59", 1.68, 1, 2, 190801, "2025/01/31 12:00:00", -363, "カリン", 1000006, 1);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 7, 64, "いつもありがとうございます！\n報酬交換ですか？\nでは、イベント報酬券とお引き換えいたしますね", "2030/01/01 14:59:59", 2.33, 2, 1, 190801, "2025/01/31 12:00:00", -363, "カリン", 1000007, 1);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (-6, 101, 61, "今度の敵は、アタシにとっても\n放ってはおけない存在だ\n少年、アタシも全力で行くからさ\n一緒に守ろう、この世界を", "2030/01/01 14:59:59", 5.18, 3, 7, 133701, "2025/01/31 12:00:00", -285, "ラビリスタ", 1020101, 10201);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (-2, 201, 61, "退屈の吹き飛ぶような\n戦いの気配がするなぁ坊や\nさっさとワタシをそこへ連れてゆけ\n世界も守ってやるさ、ついでにな", "2030/01/01 14:59:59", 8.77, 1, 2, 133901, "2025/01/31 12:00:00", -285, "クリスティーナ", 1020102, 10201);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 301, 61, "おや、私の力が必要……と？\nグレゴールが手伝うそうですよ\n私は戦わないのか、という顔ですね\n……考えておきます", "2030/01/01 14:59:59", 15.5, 6, 1, 133801, "2025/01/31 12:00:00", -285, "ネネカ", 1020103, 10201);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 101, 61, "わたしだけの歌…\n一緒に、探してくれる…？\nあなたがいれば…\nもっとがんばれるから…", "2030/01/01 14:59:59", 9.061, 2, 5, 134301, "2025/02/28 12:00:00", -285, "ランファ", 1020201, 10202);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 201, 61, "同じ唱喚士として、仲間として\n私にできることをします\n…これも、あなたが\n背中を押してくれたおかげですよ", "2030/01/01 14:59:59", 7.699, 1, 2, 134401, "2025/02/28 12:00:00", -285, "チカ", 1020202, 10202);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 101, 61, "世界の平和が私とクローチェさんに\nかかってるんですよね？\nぼっちには過大すぎる期待ですけど\nふ、二人でなら背負ってみせます！", "2030/01/01 14:59:59", 8.595, 1, 2, 134601, "2025/03/31 12:00:00", -285, "アオイ", 1020301, 10203);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 201, 61, "新しく手に入れたこの翼で…\nナイトさんがどこにいたって\nわたし、駆けつけちゃいますよっ！\nクローチェ・エアリアル発進ですっ", "2030/01/01 14:59:59", 7.758, 1, 2, 134501, "2025/03/31 12:00:00", -285, "クローチェ", 1020302, 10203);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 101, 61, "今日はダーリンとの初デート♪\n二人でショッピングして、その後は\n…って私、指名手配されてる！？\nちょ、た…助けてダーリン～！！", "2030/01/01 14:59:59", 7, 2, 6, 132302, "2025/04/30 12:00:00", -285, "ルイズマリー", 1020401, 10204);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 201, 61, "ルイちゃんのおばあちゃん優しくて\nいつもにこにこで、イロハ大好き♪\nでも一番好きなのは、角がすっごく\n大きくてかっこいいとこなんだ～♪", "2030/01/01 14:59:59", 7.904, 1, 2, 132402, "2025/04/30 12:00:00", -285, "イロハ", 1020402, 10204);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 301, 61, "ノゾミちゃんのおかげで売上が安定\nしてきたのに、臨時休業、痛すぎる\n…ま、ルイちゃんのために\n一肌脱ぐか。行くよイロハ～", "2030/01/01 14:59:59", 8.487, 4, 2, 132502, "2025/04/30 12:00:00", -285, "ソノ", 1020403, 10204);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 101, 61, "ヲ～ッホッホ♪\nあたくし様と同じお空気を吸える\nお幸運を噛みしめなさいですわ～♪\nヲ～ッホッホッホ～♪", "2030/01/01 14:59:59", 8.763, 1, 2, 134901, "2025/05/31 12:00:00", -285, "カノン", 1020502, 10205);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 201, 61, "いきますよ騎士さん！\nカノンさんと力を合わせて…力を…\n…本当にあの人なんなんです？\nこれまでになく不安なんですけど！", "2030/01/01 14:59:59", 6.417, 1, 3, 134801, "2025/05/31 12:00:00", -285, "ツムギ", 1020503, 10205);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 101, 61, "『願いが叶う海岸』か…怪しい\nだというのに、阿賀斗紫布菜たちは\n呑気に戯れている…見ていられない\n騎士クンは、わたしが守ってみせる", "2030/01/01 14:59:59", 10.335, 3, 7, 135001, "2025/06/30 12:00:00", -285, "エリス", 1020601, 10206);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 201, 61, "せっかくの夏休みなんだし\nたまにはビーチでゆっくりしましょ\n…え、もしかしてこの夏もあんまり\n休めなかったりする感じなの？", "2030/01/01 14:59:59", 6.281, 2, 4, 135101, "2025/06/30 12:00:00", -285, "シェフィ", 1020602, 10206);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 301, 61, "いっぱい。たべて\nおおきく。なると\nせーぎ。まもれる。はず\nお兄。いっしょに。スイカ。たべよ", "2030/01/01 14:59:59", 12.244, 1, 2, 135201, "2025/06/30 12:00:00", -285, "プレシア", 1020603, 10206);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 101, 61, "ひと夏の冒険のはじまりです！\nアネモネさんも楽しんでくれたら\n…できれば、もう少し\n仲良くなれたらうれしいな…", "2030/01/01 14:59:59", 6.339, 2, 8, 135301, "2025/07/31 12:00:00", -285, "クリア", 1020701, 10207);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 201, 61, "─幻の花…\n本当にあるのか謎─ですけど\n探すくらいは、\n付き合ってもいいです", "2030/01/01 14:59:59", 8.184, 7, 9, 135401, "2025/07/31 12:00:00", -285, "アネモネ", 1020702, 10207);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 101, 61, "あははっ！　笑う門には福来る！\n笑ってればきっと、複製世界にも\n未来はやってくるって信じてる！\nそうだよね、シナツちゃん！", "2030/01/01 14:59:59", 3.906, 9, 2, 129101, "2025/08/31 12:00:00", -285, "アイラ", 1020801, 10208);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 201, 61, "繰り返されるリセットの先の未来\n何度願っても手に入らなかった未来\n…でも、私は諦めない。絶対にだ\nキミも同じだろ…アイラ？", "2030/01/01 14:59:59", 14.465, 1, 2, 129201, "2025/08/31 12:00:00", -285, "シナツ", 1020802, 10208);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 301, 61, "アイラの世界のみんなも、\n一生懸命生きてるんだ…！\n…なのに、世界の危機だなんて！\nあたし、絶対、絶対力になるよ！", "2030/01/01 14:59:59", 8.662, 4, 3, 100101, "2025/08/31 12:00:00", -285, "ヒヨリ", 1020803, 10208);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 401, 61, "シナツ…もう一人の私\n彼女が大切にしている世界を\n絶対に終わらせはしない…！\n彼女と笑い合える未来のために！", "2030/01/01 14:59:59", 10.915, 1, 3, 100301, "2025/08/31 12:00:00", -285, "レイ", 1020804, 10208);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 101, 61, "あ、ど、ども…\nあ、あんま見ねぇでくれっと\nその、恥ずかしくて…\n体が熱くなって、溶けちまう…", "2030/01/01 14:59:59", 6.042, 1, 7, 135802, "2025/09/30 12:00:00", -285, "ユキノ", 1020901, 10209);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 201, 61, "なんで俺が幽霊に…意味不明だ\nこれじゃ死んでも死にきれねェ\n悪ィがこれも何かの縁だ、\nよろしく頼むぜ騎士公", "2030/01/01 14:59:59", 9.402, 4, 1, 135903, "2025/09/30 12:00:00", -285, "サツキ", 1020902, 10209);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 301, 61, "う、うじゅる…\nサツキ姉しゃまを助けるためにも\nまずは、腹ごしらえでしゅね…！\nタコ焼き、召し上がってくだしゃい", "2030/01/01 14:59:59", 8.16, 8, 1, 136902, "2025/09/30 12:00:00", -285, "ルルィ", 1020903, 10209);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 101, 61, "ひさしぶりのジオ・ゲヘナ\n歓迎パーティーで起きた殺人事件！\nランドソルの名探偵の名にかけて\n解き明かしてみせようじゃないか！", "2030/01/01 14:59:59", 5, 3, 2, 137401, "2025/10/31 12:00:00", -285, "カスミ", 1021001, 10210);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 201, 61, "…わたしはどこの誰なのでしょう\nどこから来てどこへ行くのでしょう\nこの事件の真相が分かれば、\n何かが掴めるような気がいたします", "2030/01/01 14:59:59", 8.12, 4, 1, 136001, "2025/10/31 12:00:00", -285, "アラクネ", 1021002, 10210);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 301, 61, "ナーナ、すいりとかろんぱとか、\nむずかしくてわかんないけど…\nお友だちとドーナツのためならっ\nせーいっぱいがんばるよっ！", "2030/01/01 14:59:59", 6.386, 4, 2, 136202, "2025/10/31 12:00:00", -285, "ナーナ", 1021003, 10210);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 101, 61, "騎士クンに想いを伝えたい…だから\nミソラちゃん、わたしがんばるね！\n…あれ？　わたし、なんでこんなに\n必死になってるんだろう…？", "2030/01/01 14:59:59", 7.438, 3, 4, 136402, "2025/11/30 12:00:00", -285, "ユイ", 1021101, 10211);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 201, 61, "騎士さんとのデートはわたしに\nお任せです★　なのでユイさんは\n安心して計画に専念して…たくさん\nドキドキしちゃってくださいね", "2030/01/01 14:59:59", 8.35, 1, 5, 136302, "2025/11/30 12:00:00", -285, "ミソラ", 1021102, 10211);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 101, 61, "新しい年がやってくるね！\nお正月の料理も飾りつけも、\nお姉ちゃんにお任せだよ♪\nみんなで楽しく新年を迎えよう！", "2030/01/01 14:59:59", 5, 1, 2, 136501, "2025/12/31 12:00:00", -285, "シズル", 1021201, 10212);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 201, 61, "おうちの掃除もトラブルも、 \n世界を揺るがす大ピンチも！\n今年のことは今年のうちに \nサッサと片付けちゃいますっ！", "2030/01/01 14:59:59", 5.25, 1, 2, 137902, "2025/12/31 12:00:00", -285, "リノ", 1021202, 10212);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 301, 61, "年の瀬はギルドマスターも\nつい駆け回っちゃう忙しい時期だ！\n一年いろいろあったけど\nお互いイイ年を迎えよう、少年！", "2030/01/01 14:59:59", 7.5, 1, 2, 106801, "2025/12/31 12:00:00", -285, "ラビリスタ", 1021203, 10212);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 101, 61, "漂う異国の料理の香り…それだけで\n世界中を旅した気分に浸れますね\nふふ、ほらクローチェ\nあまりはしゃぎすぎないように…♪", "2030/01/01 14:59:59", 8.204, 1, 2, 126501, "2026/01/31 12:00:00", -285, "ライラエル", 1021301, 10213);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 201, 61, "異界の姫君と煮炊きにて競い合う…\n感奮興起、いとをかし\n華やかなる祭典と相成るよう、一肌\n脱がせていただきとう存じまする", "2030/01/01 14:59:59", 7.176, 1, 2, 129701, "2026/01/31 12:00:00", -285, "ネフィ＝ネラ", 1021302, 10213);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 301, 61, "『ビストロプリンセス』のために\n料理の特訓を重ねてまいりました\nこの料理で騎士様の…い、いえ\n皆様の心とお腹を満たしますわ！", "2030/01/01 14:59:59", 8.602, 1, 5, 133101, "2026/01/31 12:00:00", -285, "ヴァイオレット", 1021303, 10213);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 102, 61, "多様な味わいが織りなすハーモニー\nそれこそが我が国の矜持です\nもしもそれを乱すようであれば\nわたしも優しくはありませんよ？", "2030/01/01 14:59:59", 10.14, 1, 3, 138101, "2026/02/06 12:00:00", -285, "ライラエル", 1021304, 10213);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 202, 61, "煉獄の穢土にてひと際輝く民草の心\n此れを守護りまするがわっちの責務\n如何な困難待ち受けようと\n不退転の矜持に揺らぎはありんせん", "2030/01/01 14:59:59", 10.152, 1, 7, 138201, "2026/02/06 12:00:00", -285, "ネフィ＝ネラ", 1021305, 10213);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 302, 61, "裏世界の皆様は危機を脱し、\n残るはランドソルの皆様のみ…\n彼らを救い出すために、どうか…\nお立ち下さいペコリーヌ姫…！", "2030/01/01 14:59:59", 9.688, 4, 3, 138001, "2026/02/06 12:00:00", -285, "ヴァイオレット", 1021306, 10213);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 401, 61, "みなさん、お待たせしちゃいました\nペコリーヌ、完全復活です☆\nみなさんの食卓を守るため\nもう二度と、わたしはめげません！", "2030/01/01 14:59:59", 5.928, 2, 1, 138301, "2026/02/12 12:00:00", -285, "ペコリーヌ", 1021307, 10213);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 101, 61, "成行きで参加することになっちゃっ\nた尻相撲大会。ううっ、恥ずかしい\nけどやるしかないよね。…騎士さん\nいっぱい応援してくださいね？", "2030/01/01 14:59:59", 9.19, 4, 2, 138702, "2026/02/28 12:00:00", -285, "ワカナ", 1021401, 10214);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 201, 61, "「お姉ちゃんを守れる自分になる」\nあの日の約束、今こそ果たしてみせ\nます。例えお姉ちゃんに背くことに\nなっても。例えそれが尻相撲でも！", "2030/01/01 14:59:59", 8.724, 1, 3, 138802, "2026/02/28 12:00:00", -285, "シオリ", 1021402, 10214);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 101, 61, "私がへんたいふしんしゃさんって…\nただ生きているだけなのに、ひどい\n…まぁ死んでるんですけど…とか\n言ってる暇もない感じですか？", "2030/01/01 14:59:59", 7.758, 4, 1, 138902, "2026/03/31 12:00:00", -285, "グレイス", 1021501, 10215);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 201, 61, "あの、助けてください！\n私がへんたいふしんしゃさんに\nなっちゃったみたいなんです…！\nどういう意味かは私もわかりません", "2030/01/01 14:59:59", 6.375, 6, 4, 139002, "2026/03/31 12:00:00", -285, "キョウカ", 1021502, 10215);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 301, 61, "ましゃか、グレイス姉しゃまたちが\nへんたいふしんしゃさんだなんて…\n騎士しゃん。あたちたちも協力ちて\n二人の破滅エンドを回避ちましょう", "2030/01/01 14:59:59", 6.173, 6, 1, 136902, "2026/03/31 12:00:00", -285, "ルルィ", 1021503, 10215);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 101, 61, "違う世界に来ちゃうし、\n驚きの連続だけど…\nわたしも精いっぱい頑張ります！\nアストルムのみんなと一緒に！", "2030/01/01 14:59:59", 4.202, 6, 2, 139202, "2026/04/30 12:00:00", -285, "ミホ", 1021601, 10216);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 201, 61, "想定外の事象が発生したな…だが\nいかなる苦境も切り抜けてみせる\nいつもの自分とは違う姿になっても\nわたしはわたし、西住流だ", "2030/01/01 14:59:59", 2.842, 6, 1, 139302, "2026/04/30 12:00:00", -285, "マホ", 1021602, 10216);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 301, 61, "何でこんなことになっているのか\n全然わからないけど、迷ってる暇は\nないわ。黒森峰の次期隊長として、\n前進あるのみ！　これも戦車道よ！", "2030/01/01 14:59:59", 4.598, 4, 1, 139402, "2026/04/30 12:00:00", -285, "エリカ", 1021603, 10216);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 101, 61, "わたくしたちの悲願は、ロストさせ\nてしまった方々をお助けすること…\nそのためなら、どのような辛苦にも\n耐え抜いてみせます…！", "2030/01/01 14:59:59", 6.533, 4, 3, 125802, "2026/05/31 12:00:00", -285, "リリ", 1021701, 10217);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 301, 61, "みんなも。せーぎも。\nクリアも。パパ、も。\nぜったい、たすける。\nみててね。お兄。", "2030/01/01 14:59:59", 5, 3, 3, 126102, "2026/05/31 12:00:00", -285, "プレシア", 1021702, 10217);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 201, 61, "癒しの力を使うこと…\nもう、ためらいません！\nモネちゃんやお兄さん…\nみんなに許してもらうためにも！", "2030/01/01 14:59:59", 5.214, 3, 4, 126002, "2026/05/31 12:00:00", -285, "クリア", 1021703, 10217);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 102, 61, "ヴァルキュリア─皆様を助けたい\nという願いを、力にできるのなら…\nわたくしたちは、きっと誰にも\n負けません！　一意専心です…！", "2030/01/01 14:59:59", 8.781, 1, 3, 139501, "2026/05/31 12:00:00", -285, "リリ", 1021704, 10217);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 202, 61, "このヴァルキュリアって職業、\nまるで天使みたいな格好ですよね\nうーん…『聖女』ちゃんって\n呼ばれるよりは、マシかな？", "2030/01/01 14:59:59", 6.529, 2, 1, 139601, "2026/05/31 12:00:00", -285, "クリア", 1021705, 10217);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 302, 61, "ばるきり。もーど。\nはね。まっしろ。\nはっぴーちゃんと。おなじ。\nいいかんじ。", "2030/01/01 14:59:59", 3.195, 3, 2, 139701, "2026/05/31 12:00:00", -285, "プレシア", 1021706, 10217);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 101, 61, "ダーリンと一緒に南の島で\nリゾート開発なんて夢みたい♪\nああ…幸せ、最高の夏だわ…\n触れたら爆発さえしなければ～…っ", "2030/01/01 14:59:59", 12.43, 2, 3, 139902, "2026/06/30 12:00:00", -285, "ルイズマリー", 1021801, 10218);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 201, 61, "青い空、白い雲…無人島リゾートで\n大儲けですわ～♪　こらこらそこ、\nイチャついてるんじゃないですのよ\n触れたらドカンですわよ、ドカン！", "2030/01/01 14:59:59", 6.35, 2, 3, 140001, "2026/06/30 12:00:00", -285, "クレジッタ", 1021802, 10218);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 101, 61, "みんなはかわいいぼくを見られて、\nぼくはみんなからラヴをもらう♡\n最高のウィンウィンだよね、これ♡\nで、最後はお兄さんをドレーに…♡", "2030/01/01 14:59:59", 10.23, 1, 5, 140102, "2026/07/31 12:00:00", -285, "フブキ", 1021901, 10219);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 201, 61, "けんぞくとたくさん遊ぶためにも、\nみんなからラヴをもらわなくちゃ♪\nバズっちゃおー作戦、\n一緒に考えてね！　けんぞくぅ♪", "2030/01/01 14:59:59", 5.584, 1, 2, 140201, "2026/07/31 12:00:00", -285, "ヴァンピィ", 1021902, 10219);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 201, 61, "あっちもこっちも、\nエマージェンシーですっ！\nみんなのピンチを助けるために\n行きましょうっ、ナイトさんっ！", "2030/01/01 14:59:59", 2.8, 6, 3, 126401, "2026/08/31 12:00:00", -285, "クローチェ", 1022001, 10220);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 101, 61, "みんながあたしを許してくれても…\nあたしは、あたしを許せない\nそれでも…この世界が危ないなら\n迷ってなんか、いられない", "2030/01/01 14:59:59", 8.9, 4, 3, 127802, "2026/08/31 12:00:00", -285, "ヴルム", 1022002, 10220);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 202, 61, "クローチェ、サブマリンモードっ\n換装完了ですっ♪\nどんな荒波も、ナイトさんとなら\n越えちゃいますからっ！", "2030/01/01 14:59:59", 4.49, 2, 1, 140602, "2026/08/31 12:00:00", -285, "クローチェ", 1022003, 10220);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 102, 61, "偽物でも、創り物でもいい\nあたしの中にある気持ちは、\nあたしの本物だから\n今度こそ、この力で守ってみせる", "2030/01/01 14:59:59", 9.42, 1, 3, 140501, "2026/08/31 12:00:00", -285, "ヴルム", 1022004, 10220);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 301, 61, "世界と向き合うなんてこと…\n私には、わからない\nそれでも、受けた借りは\nちゃんと返さないとね", "2030/01/01 14:59:59", 7, 4, 1, 140402, "2026/08/31 12:00:00", -285, "リーザ", 1022005, 10220);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 101, 61, "ゲームの世界、ね\n分からないことばかりだけれど\nやることは変わらないわ\nどんな場所でもわたしは負けない！", "2030/01/01 14:59:59", 8.61, 1, 3, 141101, "2026/10/31 12:00:00", -285, "アーモンドアイ", 1022101, 10221);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 201, 61, "ゴルシさんは相変わらずやねぇ…\nまぁせっかくの異世界やし\nいつもと違うレース、\n楽しませてもらいましょ", "2030/01/01 14:59:59", 3.55, 6, 1, 141201, "2026/10/31 12:00:00", -285, "ラッキーライラック", 1022102, 10221);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 301, 61, "なんて美しい世界でしょう…！\n現実では見られない景色ばかり\nぜひ一度、この世界の大自然を\n隅から隅まで駆け抜けてみたいです", "2030/01/01 14:59:59", 8.26, 2, 1, 141301, "2026/10/31 12:00:00", -285, "デアリングタクト", 1022103, 10221);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 401, 61, "来ったぞ～来ったぞ～\nアストルム～っと！\nな～んか平和そうな世界だな\nちょっくら盛り上げてくっか！", "2030/01/01 14:59:59", 8.79, 2, 1, 141001, "2026/10/31 12:00:00", -285, "ゴールドシップ", 1022104, 10221);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 101, 61, "ゲームの世界、ね\n分からないことばかりだけれど\nやることは変わらないわ\nどんな場所でもわたしは負けない！", "2030/01/01 14:59:59", 8.61, 1, 3, 141101, "2026/10/31 12:00:00", -285, "アーモンドアイ", 1022105, 10221);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 202, 61, "（剣と魔法！　ええなぁ～！\nうちも魔法覚えられるやろか\nレースの後に花咲かせたり…\nくぅ～っ！　はよ試したいわ！）", "2030/01/01 14:59:59", 2.69, 1, 2, 141201, "2026/10/31 12:00:00", -285, "ラッキーライラック", 1022106, 10221);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 301, 61, "なんて美しい世界でしょう…！\n現実では見られない景色ばかり\nぜひ一度、この世界の大自然を\n隅から隅まで駆け抜けてみたいです", "2030/01/01 14:59:59", 8.26, 2, 1, 141301, "2026/10/31 12:00:00", -285, "デアリングタクト", 1022107, 10221);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 401, 61, "来ったぞ～来ったぞ～\nアストルム～っと！\nな～んか平和そうな世界だな\nちょっくら盛り上げてくっか！", "2030/01/01 14:59:59", 8.79, 2, 1, 141001, "2026/10/31 12:00:00", -285, "ゴールドシップ", 1022108, 10221);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 1, 62, "ミッションをクリアすると、\n報酬がもらえますよ！\n頑張ってください", "2030/01/01 14:59:59", 3.414, 1, 2, 190805, "2026/04/10 12:00:00", -416.5, "カリン", 2000001, 2);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 2, 62, "ミッションをクリアして、\n報酬をゲットしましょう！", "2030/01/01 14:59:59", 3.099, 1, 2, 190805, "2026/04/10 12:00:00", -416.5, "カリン", 2000002, 2);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 3, 63, "受け取ることができる\n報酬があるようです\n確認してみてください", "2030/01/01 14:59:59", 2.801, 1, 2, 190805, "2026/04/10 12:00:00", -416.5, "カリン", 2000003, 2);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 4, 63, "報酬がもらえますよ！\nチェックしてみてください", "2030/01/01 14:59:59", 0, 2, 2, 190805, "2026/04/10 12:00:00", -416.5, "カリン", 2000004, 2);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 5, 64, "ギルド管理協会です！\nイベント報酬券をお持ちでしたら、様々なアイテムと交換できますよ", "2030/01/01 14:59:59", 2.12, 2, 1, 190805, "2026/04/10 12:00:00", -363, "カリン", 2000005, 2);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 6, 64, "お疲れさまです！\nこちらでイベント報酬券とアイテムを交換することができますよ", "2030/01/01 14:59:59", 1.68, 1, 2, 190805, "2026/04/10 12:00:00", -363, "カリン", 2000006, 2);
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 7, 64, "いつもありがとうございます！\n報酬交換ですか？\nでは、イベント報酬券とお引き換えいたしますね", "2030/01/01 14:59:59", 2.33, 2, 1, 190805, "2026/04/10 12:00:00", -363, "カリン", 2000007, 2);
